GRANT USAGE ON SCHEMA public TO hub2_mem_owner;
GRANT EXECUTE ON FUNCTION public.digest(text,text) TO hub2_mem_owner;
SET ROLE hub2_mem_owner;
CREATE FUNCTION mem.guard(h uuid,a text,d text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE c jsonb;BEGIN IF session_user NOT IN ('hub2_mem','hub2_worker') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;c:=authz.consume_handle(h,a,d);PERFORM authz.assert_request_resource(h,b);PERFORM mem.bind_request_sources(h,b,(c->>'actor_id')::uuid,a);PERFORM authz.assert_effect(h);RETURN c;END $$;
CREATE FUNCTION mem.guard(h uuid,a text,d text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE c jsonb;BEGIN IF session_user NOT IN('hub2_mem','hub2_worker') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;c:=authz.consume_handle(h,a,d);PERFORM authz.assert_request_resource(h,c->'resource');PERFORM mem.bind_request_sources(h,c->'resource',(c->>'actor_id')::uuid,a);PERFORM authz.assert_effect(h);RETURN c;END $$;
CREATE FUNCTION mem.emit(c jsonb,a text,m uuid,r bigint,o uuid,p jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,mem AS $$ BEGIN INSERT INTO evidence.audit(actor_id,client_id,source_context_id,domain,action,aggregate_id,revision,operation_id,details) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'source_context_id')::uuid,'mem',a,m,r,o,p); INSERT INTO evidence.outbox(domain,aggregate_id,aggregate_revision,event_type,project_id,payload) VALUES('mem',m,r,a,(c->>'project_id')::uuid,p);PERFORM authz.assert_effect((c->>'handle_id')::uuid); END $$;
CREATE FUNCTION mem.replay_command(c jsonb,a text,b jsonb,d text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,mem AS $$ DECLARE r mem.command_receipts; BEGIN IF COALESCE(b->>'idempotency_key','')='' THEN RAISE EXCEPTION 'idempotency_key_required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended((c->>'actor_id')||a||(b->>'idempotency_key'),0));SELECT * INTO r FROM mem.command_receipts WHERE actor_id=(c->>'actor_id')::uuid AND action=a AND idempotency_key=b->>'idempotency_key';IF FOUND THEN IF r.fingerprint<>d THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;RETURN r.result;END IF;RETURN NULL;END $$;
CREATE FUNCTION mem.remember_command(c jsonb,a text,b jsonb,d text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,mem AS $$ BEGIN INSERT INTO mem.command_receipts(actor_id,action,idempotency_key,fingerprint,result) VALUES((c->>'actor_id')::uuid,a,b->>'idempotency_key',d,r);PERFORM authz.assert_effect((c->>'handle_id')::uuid);RETURN r;END $$;
CREATE FUNCTION mem.begin_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$
DECLARE b jsonb:=payload::jsonb;c jsonb; o mem.operations; m mem.materials; mid uuid; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.upload',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE actor_id=(c->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key' FOR UPDATE; IF FOUND THEN IF o.fingerprint<>d THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505'; END IF; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'state',o.state,'receipt',o.receipt,'staging_key',o.staging_key); END IF;
mid:=COALESCE((b->>'material_id')::uuid,gen_random_uuid()); SELECT * INTO m FROM mem.materials WHERE id=mid FOR UPDATE; IF NOT FOUND THEN PERFORM authz.assert_effect(h); INSERT INTO mem.materials(id,project_id,owner_id,origin_kind,producer,properties,provenance_state) VALUES(mid,(c->>'project_id')::uuid,(c->>'actor_id')::uuid,COALESCE(b->>'origin_kind','member_submission'),COALESCE(b->>'producer','unknown'),COALESCE(b->'properties','{}'),CASE WHEN b->>'origin_kind'='agent_processed' THEN 'pending' ELSE 'raw' END) RETURNING * INTO m; PERFORM authz.assert_effect(h); INSERT INTO mem.placements(material_id,project_id,logical_path) VALUES(mid,m.project_id,b->>'logical_path'); END IF; IF m.project_id<>(c->>'project_id')::uuid THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
PERFORM authz.assert_effect(h); INSERT INTO mem.operations(actor_id,client_id,project_id,material_id,idempotency_key,fingerprint,expected_version_id,expected_revision,origin_kind,expected_hash,expected_size,staging_key) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,m.project_id,mid,b->>'idempotency_key',d,(b->>'expected_version_id')::uuid,(b->>'expected_revision')::bigint,COALESCE(b->>'origin_kind',m.origin_kind),b->>'sha256',(b->>'size')::bigint,'staging/'||gen_random_uuid()) RETURNING * INTO o; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'material_id',mid,'state',o.state,'staging_key',o.staging_key,'business_registration','pending'); END $$;
CREATE FUNCTION mem.claim_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.upload',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF o.state='published' THEN PERFORM authz.assert_effect(h);RETURN o.receipt; END IF; IF o.state NOT IN ('prepared','uploading','verifying','verified') THEN RAISE EXCEPTION 'operation_state_conflict' USING ERRCODE='40001'; END IF; IF o.lease_until>clock_timestamp() THEN RAISE EXCEPTION 'lease_busy' USING ERRCODE='55P03'; END IF; PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='verifying',attempt=attempt+1,fencing_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '10 minutes' WHERE id=o.id RETURNING * INTO o; PERFORM authz.assert_effect(h);RETURN to_jsonb(o)-'fingerprint'; END $$;
CREATE FUNCTION mem.verify_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;obj uuid; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.upload',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE; IF NOT FOUND OR o.state<>'verifying' OR o.fencing_token IS DISTINCT FROM (b->>'fencing_token')::uuid OR o.attempt IS DISTINCT FROM (b->>'attempt')::bigint OR o.lease_until<=clock_timestamp() OR o.expected_hash<>b->>'sha256' OR o.expected_size<>(b->>'size')::bigint THEN RAISE EXCEPTION 'verification_conflict' USING ERRCODE='40001'; END IF; PERFORM authz.assert_effect(h); INSERT INTO mem.verified_objects(provider,bucket,object_key,provider_version_id,sha256,size,verification_run) VALUES(b->>'provider',b->>'bucket',b->>'object_key',b->>'provider_version_id',o.expected_hash,o.expected_size,o.id) RETURNING id INTO obj; PERFORM authz.assert_effect(h); UPDATE mem.operations SET object_id=obj,state='verified' WHERE id=o.id; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'state','verified'); END $$;
CREATE FUNCTION mem.publish_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;m mem.materials;v mem.content_versions;r jsonb; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.upload',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF o.state='published' THEN PERFORM authz.assert_effect(h);RETURN o.receipt; END IF; IF o.state<>'verified' OR o.lease_until<=clock_timestamp() OR o.fencing_token IS DISTINCT FROM (b->>'fencing_token')::uuid OR o.attempt IS DISTINCT FROM (b->>'attempt')::bigint THEN RAISE EXCEPTION 'lease_conflict' USING ERRCODE='40001'; END IF; SELECT * INTO m FROM mem.materials WHERE id=o.material_id FOR UPDATE; IF m.content_revision<>o.expected_revision OR m.current_version_id IS DISTINCT FROM o.expected_version_id OR m.state<>'active' THEN PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='conflict' WHERE id=o.id; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'state','conflict','retained_state','verified_candidate','next_step','explicit_rebase_or_branch'); END IF;
PERFORM authz.assert_effect(h); INSERT INTO mem.content_versions(material_id,object_id,sha256,size,actor_id,reason,provenance_state) VALUES(m.id,o.object_id,o.expected_hash,o.expected_size,(c->>'actor_id')::uuid,COALESCE(b->>'reason','publish'),CASE WHEN o.origin_kind='agent_processed' THEN 'pending' ELSE 'raw' END) RETURNING * INTO v; PERFORM authz.assert_effect(h); UPDATE mem.materials SET current_version_id=v.id,content_revision=content_revision+1,event_revision=event_revision+1,provenance_state=v.provenance_state WHERE id=m.id RETURNING * INTO m; r:=jsonb_build_object('operation_id',o.id,'state','published','domain_revision',m.event_revision,'content_revision',m.content_revision,'fixed_refs',jsonb_build_array(jsonb_build_object('material_id',m.id,'version_id',v.id,'sha256',v.sha256,'size',v.size)),'business_registration','pending'); PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='published',result_version_id=v.id,receipt=r WHERE id=o.id; PERFORM mem.emit(c,'material.published',m.id,m.event_revision,o.id,r); PERFORM authz.assert_effect(h);RETURN r; END $$;
CREATE FUNCTION mem.operation(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'state',o.state,'receipt',o.receipt,'attempt',o.attempt,'retained_state','preserved'); END $$;
CREATE FUNCTION mem.enumerate(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;s mem.snapshots;items jsonb; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT COALESCE(jsonb_agg(jsonb_build_object('material_id',m.id,'version_id',m.current_version_id,'sha256',(SELECT sha256 FROM mem.content_versions WHERE id=m.current_version_id),'size',(SELECT size FROM mem.content_versions WHERE id=m.current_version_id),'content_revision',m.content_revision,'metadata_revision',m.metadata_revision,'event_revision',m.event_revision,'properties',m.properties,'origin_kind',m.origin_kind,'producer',m.producer,'placements',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placement_id',p.id,'logical_path',p.logical_path,'revision',p.revision)),'[]') FROM mem.placements p WHERE p.material_id=m.id AND p.active)) ORDER BY m.id),'[]') INTO items FROM mem.materials m WHERE m.project_id=(c->>'project_id')::uuid AND m.state='active' AND (m.provenance_state<>'pending' OR EXISTS(SELECT FROM mem.content_versions own WHERE own.id=m.current_version_id AND (own.actor_id=(c->>'actor_id')::uuid OR m.owner_id=(c->>'actor_id')::uuid))) AND m.current_version_id IS NOT NULL AND mem.version_visible((c->>'actor_id')::uuid,m.current_version_id); PERFORM mem.bind_request_sources(h,jsonb_build_object('fixed_refs',items),(c->>'actor_id')::uuid,'mem.read');PERFORM authz.assert_effect(h); INSERT INTO mem.snapshots(actor_id,client_id,project_id,qualification_epoch,items,expires_at) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'project_id')::uuid,(c->>'qualification_epoch')::bigint,items,clock_timestamp()+interval '30 minutes') RETURNING * INTO s; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('snapshot_id',s.id,'returned_count',0,'total_count',jsonb_array_length(items),'next_cursor',0,'coverage','frozen_authorized_snapshot','expires_at',s.expires_at,'processing_pending',false,'contract_version','mem-snapshot-v1'); END $$;
CREATE FUNCTION mem.enumeration_page(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;s mem.snapshots;ofs integer;lim integer;items jsonb; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO s FROM mem.snapshots WHERE id=(b->>'snapshot_id')::uuid AND actor_id=(c->>'actor_id')::uuid AND client_id=(c->>'client_id')::uuid AND project_id=(c->>'project_id')::uuid; IF NOT FOUND OR s.expires_at<=clock_timestamp() OR s.qualification_epoch<>(c->>'qualification_epoch')::bigint THEN RAISE EXCEPTION 'resync_required' USING ERRCODE='40001'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(s.items) item WHERE NOT mem.version_visible((c->>'actor_id')::uuid,(item->>'version_id')::uuid)) THEN RAISE EXCEPTION 'scope_changed_resync_required' USING ERRCODE='40001'; END IF; ofs:=(b->>'cursor')::integer;lim:=LEAST(500,GREATEST(1,COALESCE((b->>'limit')::integer,100))); IF ofs<0 OR ofs>jsonb_array_length(s.items) THEN RAISE EXCEPTION 'invalid_cursor'; END IF; SELECT COALESCE(jsonb_agg(value ORDER BY ordinality),'[]') INTO items FROM jsonb_array_elements(s.items) WITH ORDINALITY WHERE ordinality>ofs AND ordinality<=ofs+lim; PERFORM mem.bind_request_sources(h,jsonb_build_object('fixed_refs',items),(c->>'actor_id')::uuid,'mem.read');PERFORM authz.assert_effect(h);PERFORM authz.assert_effect(h);RETURN jsonb_build_object('snapshot_id',s.id,'items',items,'returned_count',jsonb_array_length(items),'total_count',jsonb_array_length(s.items),'next_cursor',CASE WHEN ofs+lim<jsonb_array_length(s.items) THEN to_jsonb(ofs+lim) ELSE 'null'::jsonb END,'coverage',CASE WHEN ofs+lim>=jsonb_array_length(s.items) THEN 'complete' ELSE 'partial' END,'contract_version','mem-snapshot-v1'); END $$;
CREATE FUNCTION mem.search_materials(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;items jsonb; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT COALESCE(jsonb_agg(x),'[]') INTO items FROM (SELECT m.id material_id,m.current_version_id version_id,m.content_revision,m.metadata_revision,p.logical_path FROM mem.materials m JOIN mem.placements p ON p.material_id=m.id AND p.active WHERE m.project_id=(c->>'project_id')::uuid AND m.state='active' AND (m.provenance_state<>'pending' OR EXISTS(SELECT FROM mem.content_versions own WHERE own.id=m.current_version_id AND (own.actor_id=(c->>'actor_id')::uuid OR m.owner_id=(c->>'actor_id')::uuid))) AND m.current_version_id IS NOT NULL AND (COALESCE(b->>'query','')='' OR position(lower(b->>'query') IN lower(p.logical_path))>0 OR EXISTS(SELECT 1 FROM mem.text_index ti WHERE ti.version_id=m.current_version_id AND ti.recipe='zh-character-bigram-v1' AND ti.tokens @@ plainto_tsquery('simple',b->>'token_text'))) AND m.properties @> COALESCE(b->'properties','{}') AND mem.version_visible((c->>'actor_id')::uuid,m.current_version_id) ORDER BY m.id LIMIT LEAST(500,GREATEST(1,COALESCE((b->>'limit')::integer,100)))) x; PERFORM mem.bind_request_sources(h,jsonb_build_object('fixed_refs',items),(c->>'actor_id')::uuid,'mem.read');PERFORM authz.assert_effect(h);PERFORM authz.assert_effect(h);RETURN jsonb_build_object('items',items,'coverage','ranked_query_not_enumeration','recipe','literal-name-json-zh-character-bigram-v1','processing_pending',true); END $$;
CREATE FUNCTION mem.read_version(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;v record;r uuid; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT cv.*,o.provider,o.bucket,o.object_key,o.provider_version_id,o.availability INTO v FROM mem.content_versions cv JOIN mem.materials m ON m.id=cv.material_id JOIN mem.verified_objects o ON o.id=cv.object_id WHERE cv.material_id=(b->>'material_id')::uuid AND cv.id=(b->>'version_id')::uuid AND m.project_id=(c->>'project_id')::uuid AND mem.version_visible((c->>'actor_id')::uuid,cv.id); IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; PERFORM authz.assert_effect(h); INSERT INTO mem.read_receipts(actor_id,client_id,material_id,version_id,sha256,range_start,range_end,complete,state) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,v.material_id,v.id,v.sha256,0,v.size,v.size>=0,'prepared') RETURNING id INTO r; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','prepared','read_receipt_id',r,'fixed_ref',jsonb_build_object('material_id',v.material_id,'version_id',v.id,'sha256',v.sha256,'size',v.size,'provenance_state',v.provenance_state,'source_stale',EXISTS(SELECT 1 FROM mem.stale_versions WHERE version_id=v.id)),'object',jsonb_build_object('provider',v.provider,'bucket',v.bucket,'key',v.object_key,'version_id',v.provider_version_id),'availability',v.availability); END $$;
CREATE FUNCTION mem.record_read(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.read_receipts; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.read',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO r FROM mem.read_receipts WHERE id=(b->>'read_receipt_id')::uuid AND actor_id=(c->>'actor_id')::uuid AND client_id=(c->>'client_id')::uuid AND EXISTS(SELECT 1 FROM mem.materials m WHERE m.id=material_id AND m.project_id=(c->>'project_id')::uuid) AND mem.version_visible((c->>'actor_id')::uuid,version_id) FOR UPDATE; IF NOT FOUND OR b->>'state' NOT IN ('sent','acknowledged') OR (b->>'state'='acknowledged' AND r.state='prepared') THEN RAISE EXCEPTION 'read_receipt_conflict' USING ERRCODE='40001'; END IF; PERFORM authz.assert_effect(h); UPDATE mem.read_receipts SET state=b->>'state' WHERE id=r.id; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('read_receipt_id',r.id,'state',b->>'state'); END $$;
CREATE FUNCTION mem.patch_placement(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;p mem.placements;m mem.materials; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.write',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'patch_placement',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; SELECT * INTO p FROM mem.placements WHERE id=(b->>'placement_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE; IF NOT FOUND OR p.revision IS DISTINCT FROM (b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001'; END IF; PERFORM authz.assert_effect(h); UPDATE mem.placements SET logical_path=b->>'logical_path',revision=revision+1 WHERE id=p.id RETURNING * INTO p; PERFORM authz.assert_effect(h); UPDATE mem.materials SET metadata_revision=metadata_revision+1,event_revision=event_revision+1 WHERE id=p.material_id RETURNING * INTO m; PERFORM mem.emit(c,'placement.changed',m.id,m.event_revision,NULL,jsonb_build_object('placement_id',p.id,'revision',p.revision)); PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'patch_placement',b,d,jsonb_build_object('state','updated','placement_id',p.id,'domain_revision',m.event_revision,'metadata_revision',m.metadata_revision,'content_revision',m.content_revision)); END $$;
CREATE FUNCTION mem.trash_material(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;m mem.materials; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.delete',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'trash_material',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; SELECT * INTO m FROM mem.materials WHERE id=(b->>'material_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE; IF NOT FOUND OR m.event_revision IS DISTINCT FROM (b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001'; END IF; PERFORM authz.assert_effect(h); UPDATE mem.materials SET state=CASE WHEN COALESCE((b->>'restore')::boolean,false) THEN 'active' ELSE 'trashed' END,event_revision=event_revision+1 WHERE id=m.id RETURNING * INTO m; PERFORM authz.assert_effect(h); UPDATE mem.placements SET active=m.state='active' WHERE material_id=m.id; PERFORM mem.emit(c,'material.lifecycle',m.id,m.event_revision,NULL,jsonb_build_object('state',m.state)); PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'trash_material',b,d,jsonb_build_object('state',m.state,'domain_revision',m.event_revision)); END $$;
CREATE FUNCTION mem.restore_content(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;m mem.materials;old mem.content_versions;v mem.content_versions; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.write',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'restore_content',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; SELECT * INTO m FROM mem.materials WHERE id=(b->>'material_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE; IF NOT FOUND OR m.content_revision IS DISTINCT FROM (b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001'; END IF; SELECT * INTO old FROM mem.content_versions WHERE material_id=m.id AND id=(b->>'version_id')::uuid; IF NOT FOUND OR old.provenance_state='pending' THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; PERFORM authz.assert_effect(h); INSERT INTO mem.content_versions(material_id,object_id,sha256,size,actor_id,reason,provenance_state) VALUES(m.id,old.object_id,old.sha256,old.size,(c->>'actor_id')::uuid,'compensating_restore',old.provenance_state) RETURNING * INTO v; PERFORM authz.assert_effect(h); UPDATE mem.materials SET current_version_id=v.id,content_revision=content_revision+1,event_revision=event_revision+1,provenance_state=v.provenance_state WHERE id=m.id RETURNING * INTO m; PERFORM authz.assert_effect(h); INSERT INTO mem.source_edges(output_version_id,input_version_id,derivation_kind) VALUES(v.id,old.id,'compensating_restore'); PERFORM mem.emit(c,'material.restored',m.id,m.event_revision,NULL,jsonb_build_object('version_id',v.id,'restored_from',old.id)); PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'restore_content',b,d,jsonb_build_object('state','restored','domain_revision',m.event_revision,'fixed_refs',jsonb_build_array(jsonb_build_object('material_id',m.id,'version_id',v.id,'sha256',v.sha256,'size',v.size)))); END $$;

CREATE FUNCTION mem.source_closure(v uuid) RETURNS TABLE(version_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ WITH RECURSIVE walk(id) AS (SELECT v UNION SELECT e.input_version_id FROM mem.source_edges e JOIN walk w ON e.output_version_id=w.id) SELECT id FROM walk $$;
CREATE FUNCTION mem.assert_version_sources(h uuid,v uuid,a text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$
DECLARE resources jsonb;output mem.content_versions;disclosed boolean;
BEGIN
 SELECT * INTO output FROM mem.content_versions WHERE id=v;
 IF output.id IS NULL OR (output.provenance_state='pending' AND (a='mem.share' OR (output.actor_id IS DISTINCT FROM (SELECT actor_id FROM authz.effect_identity(h)) AND NOT EXISTS(SELECT FROM mem.materials m WHERE m.id=output.material_id AND m.owner_id=(SELECT actor_id FROM authz.effect_identity(h)))))) OR a NOT IN('mem.read','mem.share') OR a IS NULL THEN RAISE EXCEPTION 'unknown_source' USING ERRCODE='42501';END IF;
 disclosed:=a='mem.read' AND EXISTS(SELECT FROM mem.disclosures d WHERE d.output_version_id=v AND d.state='active' AND d.manifest->>'continued_source_access'='not_required');
 SELECT COALESCE(jsonb_agg(jsonb_build_object('project_id',m.project_id,'material_id',m.id,'version_id',cv.id,'sha256',cv.sha256) ORDER BY m.project_id,m.id,cv.id),'[]') INTO resources FROM mem.source_closure(v) cl JOIN mem.content_versions cv ON cv.id=cl.version_id JOIN mem.materials m ON m.id=cv.material_id WHERE NOT disclosed OR cl.version_id=v;
 IF jsonb_array_length(resources)=0 THEN RAISE EXCEPTION 'unknown_source' USING ERRCODE='42501';END IF;
 PERFORM authz.assert_sources(h,resources,a);
END $$;
CREATE FUNCTION mem.bind_request_sources(h uuid,b jsonb,actor uuid,a text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$
DECLARE v text;ref jsonb;run mem.processing_runs;ctx record;
BEGIN
 -- Fixed-reference claims are resolved to actual immutable versions and recursive database edges.
 FOR v IN SELECT DISTINCT value #>> '{}' FROM jsonb_path_query((CASE WHEN a='mem.process' THEN b-'outputs' ELSE b END)-'properties'-'recipe', '$.**.version_id') value LOOP
  IF v IS NOT NULL THEN PERFORM mem.assert_version_sources(h,v::uuid,'mem.read');END IF;
 END LOOP;
 IF b->>'run_id' IS NOT NULL THEN
  SELECT * INTO run FROM mem.processing_runs WHERE id=(b->>'run_id')::uuid;
  IF run.id IS NOT NULL THEN FOR ref IN SELECT value FROM jsonb_array_elements(run.inputs) LOOP PERFORM mem.assert_version_sources(h,(ref->>'version_id')::uuid,'mem.read');END LOOP;END IF;
 END IF;
 IF b->>'context_id' IS NOT NULL THEN
  FOR ctx IN SELECT src.version_id FROM v8.context_sources src WHERE src.context_id=(b->>'context_id')::uuid LOOP
   IF NOT mem.version_visible(actor,ctx.version_id) THEN CONTINUE;END IF;
   PERFORM mem.assert_version_sources(h,ctx.version_id,'mem.read');
  END LOOP;
 END IF;
END $$;
CREATE FUNCTION mem.version_visible(actor uuid,v uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ SELECT EXISTS(SELECT 1 FROM mem.content_versions WHERE id=v AND (provenance_state<>'pending' OR actor_id=actor OR EXISTS(SELECT FROM mem.materials m WHERE m.id=material_id AND m.owner_id=actor))) AND (EXISTS(SELECT 1 FROM mem.disclosures d JOIN mem.content_versions cv ON cv.id=d.output_version_id JOIN mem.materials m ON m.id=cv.material_id WHERE d.output_version_id=v AND d.state='active' AND d.audience_project_id=m.project_id AND d.manifest->>'continued_source_access'='not_required' AND authz.can_read_resource(actor,m.project_id,jsonb_build_object('project_id',m.project_id,'material_id',m.id))) OR NOT EXISTS(SELECT 1 FROM mem.source_closure(v) c JOIN mem.content_versions cv ON cv.id=c.version_id JOIN mem.materials m ON m.id=cv.material_id WHERE NOT authz.can_read_resource(actor,m.project_id,jsonb_build_object('project_id',m.project_id,'material_id',m.id)))) $$;
CREATE FUNCTION mem.begin_processing(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.processing_runs;i jsonb;rf text; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;c:=mem.guard(h,'mem.process',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; FOR i IN SELECT value FROM jsonb_array_elements(b->'inputs') LOOP IF NOT EXISTS(SELECT 1 FROM mem.content_versions WHERE id=(i->>'version_id')::uuid AND material_id=(i->>'material_id')::uuid AND sha256=i->>'sha256') OR NOT mem.version_visible((c->>'actor_id')::uuid,(i->>'version_id')::uuid) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; END LOOP; SELECT * INTO r FROM mem.processing_runs WHERE actor_id=(c->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key' FOR UPDATE; IF FOUND THEN IF r.fingerprint<>d THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505'; END IF;PERFORM authz.assert_effect(h);RETURN to_jsonb(r)-'fingerprint'; END IF; rf:=encode(public.digest(jsonb_build_object('inputs',b->'inputs','recipe',b->'recipe','output_kind',b->>'output_kind')::text,'sha256'),'hex');SELECT * INTO r FROM mem.processing_runs WHERE project_id=(c->>'project_id')::uuid AND reuse_fingerprint=rf AND technical_state='succeeded' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(outputs) oo JOIN mem.stale_versions sv ON sv.version_id=(oo->>'version_id')::uuid) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(outputs) oo WHERE NOT mem.version_visible((c->>'actor_id')::uuid,(oo->>'version_id')::uuid)) ORDER BY id LIMIT 1;IF FOUND THEN PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','reused','run_id',r.id,'fixed_refs',r.outputs,'coverage',r.coverage,'semantic_status','not_asserted');END IF;PERFORM authz.assert_effect(h); INSERT INTO mem.processing_runs(project_id,actor_id,client_id,idempotency_key,fingerprint,reuse_fingerprint,output_kind,recipe,inputs,coverage) VALUES((c->>'project_id')::uuid,(c->>'actor_id')::uuid,(c->>'client_id')::uuid,b->>'idempotency_key',d,rf,b->>'output_kind',b->'recipe',b->'inputs',b->>'coverage') RETURNING * INTO r; PERFORM authz.assert_effect(h);RETURN to_jsonb(r)-'fingerprint'; END $$;
CREATE FUNCTION mem.finish_processing(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.processing_runs;i jsonb;o jsonb;m mem.materials; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;c:=mem.guard(h,'mem.process',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; PERFORM pg_advisory_xact_lock(2332001); SELECT * INTO r FROM mem.processing_runs WHERE id=(b->>'run_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE; IF NOT FOUND OR r.fencing_token IS DISTINCT FROM (b->>'fencing_token')::uuid OR r.attempt IS DISTINCT FROM (b->>'attempt')::bigint OR r.lease_until<=clock_timestamp() OR r.technical_state<>'prepared' OR r.output_kind IS DISTINCT FROM b->>'output_kind' THEN RAISE EXCEPTION 'lease_conflict' USING ERRCODE='40001'; END IF; FOR o IN SELECT value FROM jsonb_array_elements(b->'outputs') LOOP SELECT mm.* INTO m FROM mem.content_versions cv JOIN mem.materials mm ON mm.id=cv.material_id WHERE cv.id=(o->>'version_id')::uuid AND cv.material_id=(o->>'material_id')::uuid AND cv.sha256=o->>'sha256' AND mm.project_id=r.project_id AND cv.provenance_state='pending' AND mm.current_version_id=cv.id FOR UPDATE OF mm; IF NOT FOUND THEN RAISE EXCEPTION 'output_conflict' USING ERRCODE='40001'; END IF; FOR i IN SELECT value FROM jsonb_array_elements(r.inputs) LOOP IF NOT mem.version_visible((c->>'actor_id')::uuid,(i->>'version_id')::uuid) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF EXISTS(SELECT 1 FROM mem.source_closure((i->>'version_id')::uuid) WHERE version_id=(o->>'version_id')::uuid) THEN RAISE EXCEPTION 'source_cycle' USING ERRCODE='40001'; END IF; PERFORM authz.assert_effect(h); INSERT INTO mem.source_edges(output_version_id,input_version_id,run_id,derivation_kind) VALUES((o->>'version_id')::uuid,(i->>'version_id')::uuid,r.id,b->>'output_kind'); END LOOP; PERFORM authz.assert_effect(h); UPDATE mem.content_versions SET provenance_state='declared' WHERE id=(o->>'version_id')::uuid; PERFORM authz.assert_effect(h); UPDATE mem.materials SET event_revision=event_revision+1,provenance_state='declared' WHERE id=m.id RETURNING * INTO m; PERFORM mem.emit(c,'processing.output',m.id,m.event_revision,r.id,jsonb_build_object('run_id',r.id,'version_id',o->>'version_id')); END LOOP; PERFORM authz.assert_effect(h); UPDATE mem.processing_runs SET outputs=b->'outputs',technical_state='succeeded' WHERE id=r.id; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('run_id',r.id,'state','succeeded','semantic_status','not_asserted','coverage',r.coverage); END $$;
CREATE FUNCTION mem.invalidate_source(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;inv uuid;v uuid;m mem.materials;n integer:=0; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;c:=mem.guard(h,'mem.correct',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'invalidate_source',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; IF NOT EXISTS(SELECT 1 FROM mem.content_versions cv JOIN mem.materials mm ON mm.id=cv.material_id WHERE cv.id=(b->>'version_id')::uuid AND mm.project_id=(c->>'project_id')::uuid) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;PERFORM authz.assert_effect(h); INSERT INTO mem.invalidations(source_version_id,reason,actor_id) VALUES((b->>'version_id')::uuid,b->>'reason',(c->>'actor_id')::uuid) RETURNING id INTO inv; FOR v IN WITH RECURSIVE w(id) AS(SELECT (b->>'version_id')::uuid UNION SELECT e.output_version_id FROM mem.source_edges e JOIN w ON e.input_version_id=w.id) SELECT id FROM w LOOP PERFORM authz.assert_effect(h); INSERT INTO mem.stale_versions VALUES(v,inv) ON CONFLICT DO NOTHING; IF FOUND THEN n:=n+1;SELECT mm.* INTO m FROM mem.content_versions cv JOIN mem.materials mm ON mm.id=cv.material_id WHERE cv.id=v FOR UPDATE OF mm;PERFORM authz.assert_effect(h); UPDATE mem.materials SET event_revision=event_revision+1 WHERE id=m.id RETURNING * INTO m;PERFORM mem.emit(c,'source.invalidated',m.id,m.event_revision,inv,jsonb_build_object('version_id',v,'reason',b->>'reason','invalidation_id',inv)); END IF; END LOOP; PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'invalidate_source',b,d,jsonb_build_object('state','invalidated','invalidation_id',inv,'affected_count',n)); END $$;
GRANT EXECUTE ON FUNCTION mem.begin_processing(uuid,text,text),mem.finish_processing(uuid,text,text),mem.invalidate_source(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.disclose_manifest(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;v mem.content_versions;actual jsonb;supplied jsonb;src record;did uuid;m mem.materials; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;c:=mem.guard(h,'mem.share',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'disclose_manifest',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; SELECT cv.* INTO v FROM mem.content_versions cv JOIN mem.materials mm ON mm.id=cv.material_id WHERE cv.id=(b->>'version_id')::uuid AND cv.sha256=b->>'output_hash' AND mm.project_id=(c->>'project_id')::uuid AND mm.provenance_state<>'pending'; IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;PERFORM mem.assert_version_sources(h,v.id,'mem.share');SELECT COALESCE(jsonb_agg(version_id::text ORDER BY version_id),'[]') INTO actual FROM mem.source_closure(v.id) WHERE version_id<>v.id;SELECT COALESCE(jsonb_agg(value ORDER BY value),'[]') INTO supplied FROM jsonb_array_elements_text(b->'actual_source_closure'); IF actual IS DISTINCT FROM supplied THEN RAISE EXCEPTION 'source_closure_mismatch' USING ERRCODE='40001'; END IF;  IF (b->>'audience_project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'audience_must_match_output_project' USING ERRCODE='42501'; END IF; PERFORM authz.assert_effect(h); INSERT INTO mem.disclosures(output_version_id,output_hash,actual_source_closure,audience_project_id,actor_id,manifest) VALUES(v.id,v.sha256,actual,(b->>'audience_project_id')::uuid,(c->>'actor_id')::uuid,b) RETURNING id INTO did; PERFORM authz.assert_effect(h); UPDATE mem.materials SET event_revision=event_revision+1 WHERE id=v.material_id RETURNING * INTO m; PERFORM mem.emit(c,'disclosure.authorized',m.id,m.event_revision,did,jsonb_build_object('disclosure_id',did,'version_id',v.id,'quality_status','publisher_asserted'));PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'disclose_manifest',b,d,jsonb_build_object('state','authorized','disclosure_id',did,'domain_revision',m.event_revision,'quality_status','publisher_asserted')); END $$;
CREATE FUNCTION mem.revoke_disclosure(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;replay jsonb;m mem.materials;dis mem.disclosures; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF;c:=mem.guard(h,'mem.share',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; replay:=mem.replay_command(c,'revoke_disclosure',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF; SELECT dd.* INTO dis FROM mem.disclosures dd JOIN mem.content_versions cv ON cv.id=dd.output_version_id JOIN mem.materials mm ON mm.id=cv.material_id WHERE dd.id=(b->>'disclosure_id')::uuid AND mm.project_id=(c->>'project_id')::uuid FOR UPDATE OF dd;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;PERFORM authz.assert_effect(h); UPDATE mem.disclosures SET state='revoked' WHERE id=dis.id;PERFORM authz.assert_effect(h); UPDATE mem.materials SET event_revision=event_revision+1 WHERE id=(SELECT material_id FROM mem.content_versions WHERE id=dis.output_version_id) RETURNING * INTO m;PERFORM mem.emit(c,'disclosure.revoked',m.id,m.event_revision,dis.id,jsonb_build_object('disclosure_id',dis.id));PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'revoke_disclosure',b,d,jsonb_build_object('state','revoked','domain_revision',m.event_revision));END $$;
GRANT EXECUTE ON FUNCTION mem.disclose_manifest(uuid,text,text),mem.revoke_disclosure(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.index_text(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;v mem.content_versions; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.process',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;SELECT cv.* INTO v FROM mem.content_versions cv JOIN mem.materials m ON m.id=cv.material_id WHERE cv.id=(b->>'version_id')::uuid AND cv.sha256=b->>'sha256' AND m.project_id=(c->>'project_id')::uuid;IF NOT FOUND OR NOT mem.version_visible((c->>'actor_id')::uuid,v.id) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;IF b->>'recipe'<>'zh-character-bigram-v1' THEN RAISE EXCEPTION 'unknown_recipe';END IF;PERFORM authz.assert_effect(h); INSERT INTO mem.text_index(version_id,recipe,text_content,tokens,coverage) VALUES(v.id,b->>'recipe',b->>'text',to_tsvector('simple',b->>'token_text'),b->>'coverage') ON CONFLICT(version_id) DO UPDATE SET recipe=EXCLUDED.recipe,text_content=EXCLUDED.text_content,tokens=EXCLUDED.tokens,coverage=EXCLUDED.coverage;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state','indexed','version_id',v.id,'coverage',b->>'coverage','recipe',b->>'recipe');END $$;
GRANT EXECUTE ON FUNCTION mem.index_text(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.begin_batch(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.batch_operations;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.read',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;PERFORM pg_advisory_xact_lock(hashtextextended((c->>'actor_id')||'batch'||(b->>'idempotency_key'),0));SELECT * INTO r FROM mem.batch_operations WHERE actor_id=(c->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key';IF FOUND THEN IF r.fingerprint<>d THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;ELSE PERFORM authz.assert_effect(h); INSERT INTO mem.batch_operations(actor_id,idempotency_key,fingerprint,manifest) VALUES((c->>'actor_id')::uuid,b->>'idempotency_key',d,b) RETURNING * INTO r;END IF;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',r.id,'state','prepared','coverage','manifest_registered');END $$;
GRANT EXECUTE ON FUNCTION mem.begin_batch(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.retry_processing(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.processing_runs;i jsonb;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.process',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;SELECT * INTO r FROM mem.processing_runs WHERE id=(b->>'run_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE;IF NOT FOUND OR r.attempt IS DISTINCT FROM (b->>'expected_attempt')::bigint OR r.technical_state='succeeded' OR r.lease_until>clock_timestamp() THEN RAISE EXCEPTION 'lease_conflict' USING ERRCODE='40001';END IF;FOR i IN SELECT value FROM jsonb_array_elements(r.inputs) LOOP IF NOT mem.version_visible((c->>'actor_id')::uuid,(i->>'version_id')::uuid) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;END LOOP;PERFORM authz.assert_effect(h); UPDATE mem.processing_runs SET attempt=attempt+1,fencing_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '10 minutes',technical_state='prepared' WHERE id=r.id RETURNING * INTO r;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('state',r.technical_state,'run_id',r.id,'attempt',r.attempt,'fencing_token',r.fencing_token,'lease_until',r.lease_until);END $$;
GRANT EXECUTE ON FUNCTION mem.retry_processing(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.manage_collection(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.collections;replay jsonb;result jsonb;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.write',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;replay:=mem.replay_command(c,'manage_collection',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF;IF b->>'collection_id' IS NULL THEN PERFORM authz.assert_effect(h); INSERT INTO mem.collections(project_id,name) VALUES((c->>'project_id')::uuid,b->>'name') RETURNING * INTO r;ELSE SELECT * INTO r FROM mem.collections WHERE id=(b->>'collection_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE;IF NOT FOUND OR r.revision IS DISTINCT FROM (b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); UPDATE mem.collections SET name=b->>'name',revision=revision+1 WHERE id=r.id RETURNING * INTO r;END IF;result:=jsonb_build_object('state','updated','collection_id',r.id,'domain_revision',r.revision);PERFORM mem.emit(c,'collection.changed',r.id,r.revision,NULL,result);PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'manage_collection',b,d,result);END $$;
CREATE FUNCTION mem.patch_metadata(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;m mem.materials;replay jsonb;result jsonb;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.write',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;replay:=mem.replay_command(c,'patch_metadata',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF;SELECT * INTO m FROM mem.materials WHERE id=(b->>'material_id')::uuid AND project_id=(c->>'project_id')::uuid FOR UPDATE;IF NOT FOUND OR m.metadata_revision IS DISTINCT FROM (b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); UPDATE mem.materials SET properties=properties||COALESCE(b->'properties','{}'),metadata_revision=metadata_revision+1,event_revision=event_revision+1 WHERE id=m.id RETURNING * INTO m;IF b ? 'collection_id' THEN IF b->>'collection_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mem.collections WHERE id=(b->>'collection_id')::uuid AND project_id=m.project_id) THEN RAISE EXCEPTION 'collection_scope_mismatch' USING ERRCODE='42501';END IF;PERFORM authz.assert_effect(h); UPDATE mem.placements SET collection_id=(b->>'collection_id')::uuid,revision=revision+1 WHERE material_id=m.id;END IF;result:=jsonb_build_object('state','updated','material_id',m.id,'domain_revision',m.event_revision,'metadata_revision',m.metadata_revision,'content_revision',m.content_revision);PERFORM mem.emit(c,'metadata.changed',m.id,m.event_revision,NULL,result);PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'patch_metadata',b,d,result);END $$;
GRANT EXECUTE ON FUNCTION mem.manage_collection(uuid,text,text),mem.patch_metadata(uuid,text,text) TO hub2_mem;

CREATE FUNCTION mem.rebase_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;m mem.materials;replay jsonb;result jsonb;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.upload',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;replay:=mem.replay_command(c,'rebase_upload',b,d);IF replay IS NOT NULL THEN PERFORM authz.assert_effect(h);RETURN replay;END IF;SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE;IF NOT FOUND OR o.state<>'conflict' OR o.object_id IS NULL THEN RAISE EXCEPTION 'operation_state_conflict' USING ERRCODE='40001';END IF;SELECT * INTO m FROM mem.materials WHERE id=o.material_id FOR UPDATE;IF m.state<>'active' OR m.content_revision IS DISTINCT FROM (b->>'expected_revision')::bigint OR m.current_version_id IS DISTINCT FROM (b->>'expected_version_id')::uuid THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h); UPDATE mem.operations SET expected_revision=m.content_revision,expected_version_id=m.current_version_id,state='verified',attempt=attempt+1,fencing_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '10 minutes' WHERE id=o.id RETURNING * INTO o;result:=jsonb_build_object('operation_id',o.id,'state',o.state,'attempt',o.attempt,'fencing_token',o.fencing_token,'lease_until',o.lease_until,'retained_state','same_verified_bytes','next_step','publish_rebased_candidate');PERFORM authz.assert_effect(h);RETURN mem.remember_command(c,'rebase_upload',b,d,result);END $$;
GRANT EXECUTE ON FUNCTION mem.rebase_upload(uuid,text,text) TO hub2_mem;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA mem FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.begin_upload(uuid,text,text),mem.claim_upload(uuid,text,text),mem.verify_upload(uuid,text,text),mem.publish_upload(uuid,text,text),mem.operation(uuid,text,text),mem.enumerate(uuid,text,text),mem.enumeration_page(uuid,text,text),mem.search_materials(uuid,text,text),mem.read_version(uuid,text,text),mem.record_read(uuid,text,text),mem.patch_placement(uuid,text,text),mem.trash_material(uuid,text,text),mem.restore_content(uuid,text,text) TO hub2_mem;
RESET ROLE;
GRANT EXECUTE ON FUNCTION mem.version_visible(uuid,uuid),mem.source_closure(uuid),mem.assert_version_sources(uuid,uuid,text),mem.bind_request_sources(uuid,jsonb,uuid,text) TO hub2_v8_owner;
SET ROLE hub2_mem_owner;
CREATE FUNCTION mem.delivered_ref(actor uuid,client uuid,receipt uuid,material uuid,version uuid,hash text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ SELECT EXISTS(SELECT 1 FROM mem.read_receipts r WHERE r.id=receipt AND r.actor_id=actor AND r.client_id=client AND r.material_id=material AND r.version_id=version AND r.sha256=hash AND r.state IN ('sent','acknowledged') AND r.complete AND mem.version_visible(actor,version)) $$;
REVOKE ALL ON FUNCTION mem.delivered_ref(uuid,uuid,uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.delivered_ref(uuid,uuid,uuid,uuid,uuid,text) TO hub2_v8_owner;
RESET ROLE;
SET ROLE hub2_mem_owner;
CREATE FUNCTION mem.version_stale(v uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ SELECT EXISTS(SELECT 1 FROM mem.stale_versions WHERE version_id=v) $$;
CREATE FUNCTION mem.operation_evidence(actor uuid,project uuid,op uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ SELECT jsonb_build_object('operation_id',o.id,'state',o.state,'retained_state',CASE WHEN o.object_id IS NOT NULL THEN 'verified_candidate_retained' ELSE 'staging_operation_retained' END) FROM mem.operations o WHERE o.id=op AND o.actor_id=actor AND o.project_id=project AND authz.can_read(actor,project) $$;
REVOKE ALL ON FUNCTION mem.version_stale(uuid),mem.operation_evidence(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.version_stale(uuid),mem.operation_evidence(uuid,uuid,uuid) TO hub2_v8_owner;
RESET ROLE;
